-- =====================================================================
-- 智能企业人才梯队建设平台 —— 数据集建表 + 灌数据
-- ---------------------------------------------------------------------
-- 数据来源（项目根目录下两个 CSV）：
--   员工人才梯队数据集_增强版（1000人21字段）.csv   → 1000 名员工
--   岗位画像表.csv                                 → 72 个岗位
--
-- 21 个字段没有堆在一张表里，按主题拆成 13 张：
--   字典表：  skill（技能字典）、course（课程字典）
--   岗位侧：  position（岗位画像）、pos_skill_require（核心/加分技能）、
--             pos_course_require（必备培训）
--   员工侧：  emp_employee（基本信息）、emp_salary（薪酬）、emp_performance（绩效）、
--             emp_potential（潜力评估）、resign_warning_record（流失风险）、
--             emp_talent_tag（人才标签）、emp_skill（会什么技能）、
--             training_record（已完成培训）
--   CSV 里用顿号拼起来的列表（技能标签 / 已完成培训 / 核心技能 / 加分技能 / 必备培训）
--   一律拆成关联表，不存 "A、B、C" 这种字符串，方便按技能、按课程做统计和匹配。
--
-- 执行方式：
--   cmd /c "D:\Develop\MySQL80\bin\mysql.exe -uroot -p20050312 --default-character-set=utf8mb4 < sql\talent_dataset.sql"
--
-- 注意：本脚本会 DROP 并重建上面这些表。
--   sql/talent_db.sql 里那 3 条示例数据（E001/E002/E003 和 3 个示例岗位）会被数据集取代；
--   如果这些表里已经录过手工数据，先备份再执行。
--   另外：本脚本建的 skill 表是「平表」，重跑之后技能树（分类、parent_id）会丢，
--   需要再执行一次 sql/talent_skill_tree.sql 把技能树补回来。
-- =====================================================================

CREATE DATABASE IF NOT EXISTS `talent_db` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `talent_db`;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 先删子表，再删父表
DROP TABLE IF EXISTS `training_record`;
DROP TABLE IF EXISTS `emp_skill`;
DROP TABLE IF EXISTS `emp_talent_tag`;
DROP TABLE IF EXISTS `resign_warning_record`;
DROP TABLE IF EXISTS `emp_potential`;
DROP TABLE IF EXISTS `emp_performance`;
DROP TABLE IF EXISTS `emp_salary`;
DROP TABLE IF EXISTS `emp_employee`;
DROP TABLE IF EXISTS `pos_course_require`;
DROP TABLE IF EXISTS `pos_skill_require`;
DROP TABLE IF EXISTS `resign_warning_rule`;
DROP TABLE IF EXISTS `position`;
DROP TABLE IF EXISTS `course`;
DROP TABLE IF EXISTS `skill`;

-- ----------------------------
-- 字典表
-- ----------------------------

-- 技能字典：员工会的技能、岗位要求的核心技能和加分技能，共用这一套
CREATE TABLE `skill` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `skill_name` VARCHAR(64) NOT NULL COMMENT '技能名称',
  `skill_category` VARCHAR(64) DEFAULT NULL COMMENT '技能分类，数据集未提供，留空待补',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_skill_name` (`skill_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='技能字典';

-- 课程字典：员工已完成的培训、岗位要求的必备培训，共用这一套
CREATE TABLE `course` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `course_name` VARCHAR(128) NOT NULL COMMENT '课程/培训名称',
  `course_type` VARCHAR(32) DEFAULT NULL COMMENT '课程类型，数据集未提供',
  `for_position` VARCHAR(64) DEFAULT NULL COMMENT '适用岗位',
  `difficulty` VARCHAR(16) DEFAULT NULL COMMENT '难度等级',
  `duration` INT DEFAULT 0 COMMENT '培训时长(小时)',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_course_name` (`course_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='课程字典';

-- ----------------------------
-- 岗位侧（模块二：梯队规划与预测）
-- ----------------------------

-- 岗位画像（由骨架里的 position 表扩展而来，补上了岗位画像里的十几列）
CREATE TABLE `position` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `position_name` VARCHAR(64) NOT NULL COMMENT '岗位名称',
  `department` VARCHAR(64) NOT NULL COMMENT '所属部门',
  `level_tier` VARCHAR(32) DEFAULT NULL COMMENT '职级层级',
  `job_rank` VARCHAR(32) DEFAULT NULL COMMENT '职级',
  `position_type` VARCHAR(32) DEFAULT NULL COMMENT '岗位类型',
  `perf_require` VARCHAR(64) DEFAULT NULL COMMENT '绩效要求',
  `tenure_require` VARCHAR(32) DEFAULT NULL COMMENT '司龄要求',
  `work_mode_require` VARCHAR(64) DEFAULT NULL COMMENT '办公方式要求',
  `is_manage` TINYINT DEFAULT 0 COMMENT '是否管理岗 1是 0否',
  `is_key` TINYINT DEFAULT 0 COMMENT '关键岗位标识 1是 0否（骨架字段，数据集未提供）',
  `fit_desc` VARCHAR(255) DEFAULT NULL COMMENT '适配说明',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_position` (`position_name`, `department`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='岗位画像';

-- 岗位技能要求：一个岗位多条，require_type 区分核心技能和加分技能
CREATE TABLE `pos_skill_require` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `position_id` BIGINT NOT NULL COMMENT '岗位ID',
  `skill_id` BIGINT NOT NULL COMMENT '技能ID',
  `require_type` VARCHAR(8) NOT NULL COMMENT '要求类型：核心/加分',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pos_skill` (`position_id`, `skill_id`, `require_type`),
  KEY `idx_skill` (`skill_id`),
  CONSTRAINT `fk_psk_position` FOREIGN KEY (`position_id`) REFERENCES `position` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_psk_skill` FOREIGN KEY (`skill_id`) REFERENCES `skill` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='岗位技能要求';

-- 岗位必备培训：一个岗位多条
CREATE TABLE `pos_course_require` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `position_id` BIGINT NOT NULL COMMENT '岗位ID',
  `course_id` BIGINT NOT NULL COMMENT '课程ID',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pos_course` (`position_id`, `course_id`),
  KEY `idx_course` (`course_id`),
  CONSTRAINT `fk_pcr_position` FOREIGN KEY (`position_id`) REFERENCES `position` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_pcr_course` FOREIGN KEY (`course_id`) REFERENCES `course` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='岗位必备培训';

-- ----------------------------
-- 员工侧（模块一：员工档案；其中流失风险归模块二）
-- ----------------------------

-- 员工基本信息（一张表只放"人是谁、在哪个岗、汇报给谁"）
CREATE TABLE `emp_employee` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `emp_no` VARCHAR(32) NOT NULL COMMENT '工号',
  `name` VARCHAR(64) NOT NULL COMMENT '姓名',
  `gender` VARCHAR(16) DEFAULT NULL COMMENT '性别',
  `age` INT DEFAULT NULL COMMENT '年龄',
  `department` VARCHAR(64) DEFAULT NULL COMMENT '所属部门',
  `position_id` BIGINT NOT NULL COMMENT '岗位ID，关联 position.id',
  `level_tier` VARCHAR(32) DEFAULT NULL COMMENT '职级层级',
  `job_rank` VARCHAR(32) DEFAULT NULL COMMENT '职级',
  `manager_emp_no` VARCHAR(32) DEFAULT NULL COMMENT '上级工号，空表示没有上级',
  `work_mode` VARCHAR(16) DEFAULT NULL COMMENT '办公方式',
  `tenure_years` DECIMAL(4,1) DEFAULT NULL COMMENT '司龄(年)',
  `hire_date` DATE DEFAULT NULL COMMENT '入职时间，数据集未提供，留空待补',
  `education` VARCHAR(32) DEFAULT NULL COMMENT '学历，数据集未提供，留空待补',
  `phone` VARCHAR(32) DEFAULT NULL COMMENT '联系方式，数据集未提供，留空待补',
  `status` VARCHAR(16) DEFAULT '在职' COMMENT '状态: 在职/离职/试用',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_emp_no` (`emp_no`),
  KEY `idx_position` (`position_id`),
  KEY `idx_department` (`department`),
  KEY `idx_manager` (`manager_emp_no`),
  CONSTRAINT `fk_emp_position` FOREIGN KEY (`position_id`) REFERENCES `position` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='员工基本信息';

-- 薪酬：基本年薪 + 薪酬系数（单独一张表，方便控制谁能看）
CREATE TABLE `emp_salary` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `employee_id` BIGINT NOT NULL COMMENT '员工ID',
  `base_salary` DECIMAL(12,2) DEFAULT NULL COMMENT '基本年薪(元)',
  `salary_coefficient` DECIMAL(6,3) DEFAULT NULL COMMENT '薪酬系数',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_emp` (`employee_id`),
  CONSTRAINT `fk_salary_emp` FOREIGN KEY (`employee_id`) REFERENCES `emp_employee` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='员工薪酬';

-- 绩效：按年度存，同一员工不同年份多条
CREATE TABLE `emp_performance` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `employee_id` BIGINT NOT NULL COMMENT '员工ID',
  `perf_year` INT NOT NULL COMMENT '绩效年份',
  `score` DECIMAL(5,2) DEFAULT NULL COMMENT '绩效得分',
  `grade` VARCHAR(16) DEFAULT NULL COMMENT '绩效评级',
  `dimension_scores` TEXT DEFAULT NULL COMMENT '考核维度得分(JSON)',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_emp_year` (`employee_id`, `perf_year`),
  CONSTRAINT `fk_perf_emp` FOREIGN KEY (`employee_id`) REFERENCES `emp_employee` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='员工绩效';

-- 潜力评估：评分 + 等级
CREATE TABLE `emp_potential` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `employee_id` BIGINT NOT NULL COMMENT '员工ID',
  `potential_level` VARCHAR(32) DEFAULT NULL COMMENT '潜力等级',
  `total_score` DECIMAL(5,2) DEFAULT NULL COMMENT '潜力综合得分',
  `indicator_values` TEXT DEFAULT NULL COMMENT '潜力评估指标值(JSON)',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_emp` (`employee_id`),
  CONSTRAINT `fk_potential_emp` FOREIGN KEY (`employee_id`) REFERENCES `emp_employee` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='员工潜力评估';

-- 流失风险：分值和风险等级，归模块二的流失预警用
CREATE TABLE `resign_warning_record` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `employee_id` BIGINT NOT NULL COMMENT '员工ID',
  `risk_score` DECIMAL(5,2) DEFAULT NULL COMMENT '流失风险分值',
  `warning_level` VARCHAR(16) DEFAULT NULL COMMENT '预警等级',
  `warning_time` DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '预警时间',
  `handle_status` VARCHAR(16) DEFAULT '未处理' COMMENT '处理状态',
  PRIMARY KEY (`id`),
  KEY `idx_emp` (`employee_id`),
  KEY `idx_level` (`warning_level`),
  CONSTRAINT `fk_warning_emp` FOREIGN KEY (`employee_id`) REFERENCES `emp_employee` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='流失预警记录';

-- 流失预警规则（骨架里就有的表，本数据集没有规则数据，先建空表）
CREATE TABLE `resign_warning_rule` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `rule_name` VARCHAR(64) DEFAULT NULL COMMENT '规则名称',
  `trigger_condition` VARCHAR(255) DEFAULT NULL COMMENT '触发条件',
  `warning_level` VARCHAR(16) DEFAULT NULL COMMENT '预警等级',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='流失预警规则';

-- 人才标签：单独一张表，一个人可以有多个标签，也方便保留历史
CREATE TABLE `emp_talent_tag` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `employee_id` BIGINT NOT NULL COMMENT '员工ID',
  `tag_name` VARCHAR(32) NOT NULL COMMENT '人才标签：核心骨干/储备人才/普通员工/待优化',
  `source` VARCHAR(32) DEFAULT NULL COMMENT '标签来源',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_emp_tag` (`employee_id`, `tag_name`),
  CONSTRAINT `fk_tag_emp` FOREIGN KEY (`employee_id`) REFERENCES `emp_employee` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='员工人才标签';

-- 员工技能：员工和技能字典的关联
CREATE TABLE `emp_skill` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `employee_id` BIGINT NOT NULL COMMENT '员工ID',
  `skill_id` BIGINT NOT NULL COMMENT '技能ID',
  `skill_grade` VARCHAR(16) DEFAULT NULL COMMENT '技能等级，数据集未提供',
  `master_hours` INT DEFAULT 0 COMMENT '掌握时长(小时)，数据集未提供',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_emp_skill` (`employee_id`, `skill_id`),
  KEY `idx_skill` (`skill_id`),
  CONSTRAINT `fk_es_emp` FOREIGN KEY (`employee_id`) REFERENCES `emp_employee` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_es_skill` FOREIGN KEY (`skill_id`) REFERENCES `skill` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='员工技能';

-- 培训记录：员工已完成的培训
CREATE TABLE `training_record` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `employee_id` BIGINT NOT NULL COMMENT '员工ID',
  `course_id` BIGINT NOT NULL COMMENT '课程ID',
  `status` VARCHAR(16) DEFAULT '已完成' COMMENT '状态：已完成/进行中',
  `attend_rate` DECIMAL(5,2) DEFAULT NULL COMMENT '培训参与率',
  `pass_rate` DECIMAL(5,2) DEFAULT NULL COMMENT '考核通过率',
  `improve_score` DECIMAL(5,2) DEFAULT NULL COMMENT '能力提升分值',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_emp_course` (`employee_id`, `course_id`),
  KEY `idx_course` (`course_id`),
  CONSTRAINT `fk_tr_emp` FOREIGN KEY (`employee_id`) REFERENCES `emp_employee` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_tr_course` FOREIGN KEY (`course_id`) REFERENCES `course` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='培训记录';

