SET FOREIGN_KEY_CHECKS = 1;

-- =====================================================================
-- 灌完核对一下条数
-- =====================================================================
SELECT 'skill（技能字典）'                AS `表`, COUNT(*) AS `条数` FROM `skill`
UNION ALL SELECT 'course（课程字典）',              COUNT(*) FROM `course`
UNION ALL SELECT 'position（岗位画像）',            COUNT(*) FROM `position`
UNION ALL SELECT 'pos_skill_require（岗位技能要求）', COUNT(*) FROM `pos_skill_require`
UNION ALL SELECT 'pos_course_require（岗位必备培训）', COUNT(*) FROM `pos_course_require`
UNION ALL SELECT 'emp_employee（员工基本信息）',      COUNT(*) FROM `emp_employee`
UNION ALL SELECT 'emp_salary（薪酬）',              COUNT(*) FROM `emp_salary`
UNION ALL SELECT 'emp_performance（绩效）',         COUNT(*) FROM `emp_performance`
UNION ALL SELECT 'emp_potential（潜力评估）',       COUNT(*) FROM `emp_potential`
UNION ALL SELECT 'resign_warning_record（流失风险）', COUNT(*) FROM `resign_warning_record`
UNION ALL SELECT 'emp_talent_tag（人才标签）',      COUNT(*) FROM `emp_talent_tag`
UNION ALL SELECT 'emp_skill（员工技能）',           COUNT(*) FROM `emp_skill`
UNION ALL SELECT 'training_record（已完成培训）',    COUNT(*) FROM `training_record`;
